public class Main {
    static int[] sortNumbers(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        return sorted;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = in.nextInt();
        }
        StringJoiner out = new StringJoiner(" ");
        for (int x : sortNumbers(nums)) {
            out.add(String.valueOf(x));
        }
        System.out.println(out);
    }
}

